head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/GANTT/data/GANTT_STICKY.json";   // {type:gantt, json:[{rangex,rangey,plan}]}
// ---- 차트 공통 상수 (SPCHART.md 회신 §1 일반화) ----
scwin.CHART_COLORS = ["#E52528", "#1B64DA", "#0A8060", "#F5A623", "#7B1FA2"];   // ★ 시리즈 색상 팔레트 — 현장 조정

scwin.CHART_CONFIG = {
    "tooltip": {   // 마우스오버 표시값 — 천단위 콤마 — SPCHART.md §1-7
      "format": {
        "value": function (v, ratio, id, index) { return $c.num.formatNumber(v); }
      }
    },
    "color": { "pattern": scwin.CHART_COLORS },   // 시리즈 색상 명시 (미지정 시 라이브러리 기본색) — SPCHART.md §1-3
    global: {
        bUserConf: true,
        onclick: function (x) { return; }
    },
    axis: {
        x: {
            show: false, type: "category", tick: { line: { show: false } },
            scroll: { trackRx: 10, trackRy: 10, barRx: 8, barRy: 8 }   // ★ sticky 스크롤바 스타일
        },
        y: { show: false, tick: { line: { show: false } } }
    },
    tooltip: { noUseExpand: true },
    extend: {
        gantt: {
            xTickInterval: 60,                                        // ★ x 눈금 간격(스크롤 유발)
            gridX: { show: false },
            gridY: { show: false },
            labelFormat: function (d) { return d.label; },
            label: { moveY: 10 },
            useWheelScrollY: true,
            useFreeYPosition: true
        }
    }
};

/**
 * 차트 컨테이너를 정리한다. 재조회 렌더 전 호출 — 이전 차트 잔존 방지 (SPCHART.md §1-5)
 * (resize 리스너까지 해제하려면 sb.chart.render 직접 호출로 인스턴스를 잡아 sb.chart.destroy 사용)
 */
scwin.clearChart = function (comp) {
    const el = document.getElementById(comp.getID());
    if (el) { el.innerHTML = ""; }
};

scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    scwin.clearChart(chartWrap);   // 재조회 대비 이전 차트 정리
    $c.ext.drawChartData("gantt", data, chartWrap, scwin.CHART_CONFIG);
};
